def transform(grid):
    # Output encodes the 6-pattern after rotating it 180 degrees,
    # filtered by the matching 5-pattern.
    left = [[int(v == 6) for v in row[:4]] for row in grid]
    right = [[int(v == 5) for v in row[4:]] for row in grid]
    out = [[0] * 4 for _ in range(4)]
    for r in range(4):
        for c in range(4):
            if left[3-r][3-c] and right[r][c]:
                out[r][c] = 4
    return out
